mapper.select:
SELECT f.*, o.name AS owner_name,
       CONCAT(h.building, '-', h.unit, '-', h.room_number) AS house_info
FROM fee f
LEFT JOIN owner o ON f.owner_id = o.id
LEFT JOIN house h ON f.house_id = h.id

    AND f.owner_id = #{ownerId}
    AND f.fee_type = #{feeType}
    AND f.status = #{status}

ORDER BY f.id DESC

SELECT f.*, o.name AS owner_name,
       CONCAT(h.building, '-', h.unit, '-', h.room_number) AS house_info
FROM fee f
LEFT JOIN owner o ON f.owner_id = o.id
LEFT JOIN house h ON f.house_id = h.id

    AND f.owner_id = #{ownerId}
    AND f.fee_type = #{feeType}
    AND f.status = #{status}

ORDER BY f.id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM fee

    AND owner_id = #{ownerId}
    AND fee_type = #{feeType}
    AND status = #{status}

